package com.justenoughmods.achievementguide.integration.battlearmor;
import com.github.L_Ender.cataclysm.init.*;import com.github.L_Ender.cataclysm.util.EntityUtil;import java.util.*;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.entity.*;import net.minecraft.world.item.ItemStack;import net.minecraft.world.effect.MobEffectInstance;import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;import top.theillusivec4.curios.api.SlotResult;
public final class WorldBattleArmorQuestCurios {
 public static final class Theft {public final ServerPlayer actor;public final Optional<SlotResult> nativeSlot;public final EquipmentSlot hand;public final ItemStack held;public boolean prevented;public Theft(ServerPlayer actor,Optional<SlotResult> slot,EquipmentSlot hand,ItemStack held){this.actor=actor;nativeSlot=slot;this.hand=hand;this.held=held.copy();}}
 public record Skull(ServerPlayer actor,MobEffectInstance input,boolean eligible){}
 private static final Map<LivingEntity,Skull> SKULLS=new IdentityHashMap<>();
 public static Theft queried(LivingEntity target,Optional<SlotResult> slot){var actor=WorldBattleArmorQuestProof.real(target);if(actor==null||slot.isEmpty()||!slot.get().stack().is(ModItems.STICKY_GLOVES.get()))return null;var hand=!actor.getOffhandItem().isEmpty()?EquipmentSlot.OFFHAND:EquipmentSlot.MAINHAND;var held=actor.getItemBySlot(hand);if(held.isEmpty()||held.is(ModTag.STICKY_ITEM))return null;return new Theft(actor,slot,hand,held);}
 public static void optional(Theft theft,Optional<?> actual,boolean empty){if(theft!=null&&actual==theft.nativeSlot&&!empty)theft.prevented=true;}
 public static void finish(Theft theft){if(theft!=null&&theft.prevented&&WorldBattleArmorQuestProof.real(theft.actor)!=null&&ItemStack.matches(theft.held,theft.actor.getItemBySlot(theft.hand))&&EntityUtil.isEquipped(ModItems.STICKY_GLOVES.get(),theft.actor))WorldBattleArmorQuestProof.emit(theft.actor,"v3_combat_abyss_kit");}
 public static Skull skullBefore(LivingEntity entity,MobEffectInstance effect){var actor=WorldBattleArmorQuestProof.real(entity);return actor==null?null:new Skull(actor,effect,effect.getEffect()==ModEffect.EFFECTSTUN.get()&&effect.getDuration()>0&&!actor.hasEffect(effect.getEffect())&&!actor.getCooldowns().isOnCooldown(ModItems.UNBREAKABLE_SKULL.get())&&EntityUtil.isEquipped(ModItems.UNBREAKABLE_SKULL.get(),actor));}
 public static void skullNative(Skull before,CallbackInfoReturnable<Boolean> nativeCallback){if(before!=null&&before.eligible&&nativeCallback.isCancelled()&&Boolean.FALSE.equals(nativeCallback.getReturnValue())&&!before.actor.hasEffect(ModEffect.EFFECTSTUN.get())&&before.actor.getCooldowns().isOnCooldown(ModItems.UNBREAKABLE_SKULL.get())&&SKULLS.size()<256)SKULLS.put(before.actor,before);}
 public static void effectReturned(LivingEntity entity,MobEffectInstance effect,boolean accepted){if(!(entity instanceof ServerPlayer))return;var pending=SKULLS.get(entity);if(pending==null||pending.input!=effect)return;SKULLS.remove(entity);if(!accepted&&WorldBattleArmorQuestProof.real(entity)!=null&&!entity.hasEffect(ModEffect.EFFECTSTUN.get())&&pending.actor.getCooldowns().isOnCooldown(ModItems.UNBREAKABLE_SKULL.get())&&EntityUtil.isEquipped(ModItems.UNBREAKABLE_SKULL.get(),entity))WorldBattleArmorQuestProof.emit(pending.actor,"v3_combat_abyss_kit");}
 public static void clear(UUID actor){SKULLS.keySet().removeIf(e->e.getUUID().equals(actor));}public static void clear(){SKULLS.clear();}
}
